const rows = $input.all().map(i => i.json).filter(r => r && r.id);
const BATCH = 20;
const out = [];
for (let i = 0; i < rows.length; i += BATCH) {
  const slice = rows.slice(i, i + BATCH);
  out.push({ json: {
    count: slice.length,
    fetched: rows.length,
    items_json: JSON.stringify(slice.map(r => ({ id: r.id, kind: r.kind, client_text: r.client_text, coach_said: r.coach_said }))),
  } });
}
if (!out.length) out.push({ json: { count: 0, fetched: 0, items_json: '[]' } });
return out;

