// Parse the judge's JSON and build one UPDATE statement for this batch.
let txt = '';
try { txt = $json.choices[0].message.content; } catch (e) {}
txt = String(txt).replace(/^```(json)?/m, '').replace(/```\s*$/m, '').trim();
const start = txt.indexOf('['), end = txt.lastIndexOf(']');
let verdicts = [];
try { verdicts = JSON.parse(txt.slice(start, end + 1)); } catch (e) {}

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const values = [];
let keeps = 0, removes = 0;
for (const v of verdicts) {
  if (!v || !UUID.test(String(v.id))) continue;
  const verdict = v.verdict === 'remove' ? 'remove' : 'keep';
  if (verdict === 'remove') removes++; else keeps++;
  values.push("('" + v.id + "'::uuid, '" + verdict + "')");
}
if (!values.length) {
  return { json: { update_sql: 'select 0 as updated;', keeps: 0, removes: 0, parse_ok: false } };
}
const sql = 'update sparky_segments s set metadata = jsonb_set(s.metadata, \'{qa_verdict}\', to_jsonb(v.verdict)) ' +
            'from (values ' + values.join(',') + ') as v(id, verdict) where s.id = v.id;';
return { json: { update_sql: sql, keeps, removes, parse_ok: true } };

const b = $('Build verdict SQL').all().map(i => i.json);
const fetched = $('Prepare judge batches').first().json.fetched;
const keeps = b.reduce((s, x) => s + (x.keeps || 0), 0);
const removes = b.reduce((s, x) => s + (x.removes || 0), 0);
const failed = b.filter(x => x.parse_ok === false).length;
return [{ json: {
  reviewed_this_run: keeps + removes,
  fetched_this_run: fetched,
  marked_keep: keeps,
  marked_remove: removes,
  judge_parse_failures: failed,
  note: fetched > 0
    ? 'Click Execute workflow again — it continues with the next unreviewed rows.'
    : 'All rows reviewed. Now run the final DELETE (see instructions) to drop the removes.',
} }];
